// -----------------------------------------------------------------------------
// 4. MULTILINGUAL NLP TOKENIZATION & PREDICTION ENGINE
// -----------------------------------------------------------------------------
class MudraNLPEngine {
  constructor(database) {
    this.database = database;
  }

  // Normalize text across scripts (Latin, Kannada, Tamil, Telugu, Malayalam, Devanagari)
  normalize(text) {
    if (!text) return "";
    return text
      .toLowerCase()
      .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?"'।॥]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  // Tokenize string into words and n-grams
  tokenize(text) {
    const clean = this.normalize(text);
    if (!clean) return [];
    const words = clean.split(" ").filter(w => w.length > 1);
    
    // Add bigrams and trigrams for phrase matching
    const ngrams = [];
    for (let i = 0; i < words.length - 1; i++) {
      ngrams.push(`${words[i]} ${words[i + 1]}`);
      if (i < words.length - 2) {
        ngrams.push(`${words[i]} ${words[i + 1]} ${words[i + 2]}`);
      }
    }
    return [...words, ...ngrams];
  }

  // Predict the most matching Mudra
  predict(queryText, currentLang = "en") {
    const cleanQuery = this.normalize(queryText);
    if (!cleanQuery) return null;

    const queryTokens = this.tokenize(queryText);
    const scores = [];

    for (const mudra of this.database) {
      let matchScore = 0;
      let matchedTerms = new Set();

      // Check Mudra ID, Sanskrit, and English Name directly
      if (cleanQuery.includes(mudra.id)) {
        matchScore += 40;
        matchedTerms.add(mudra.id);
      }

      // Check all multilingual keywords
      const languages = ["en", "kn", "ta", "te", "ml", "hi"];
      for (const lang of languages) {
        const keywords = mudra.keywords[lang] || [];
        const langWeight = (lang === currentLang) ? 1.4 : 1.0;

        for (const kw of keywords) {
          const normKw = this.normalize(kw);

          // 1. Exact phrase substring match in query
          if (cleanQuery.includes(normKw)) {
            const wordCount = normKw.split(" ").length;
            const points = (wordCount >= 2 ? 28 : 14) * langWeight;
            matchScore += points;
            matchedTerms.add(kw);
          } else {
            // 2. Token overlap match
            for (const token of queryTokens) {
              if (token === normKw) {
                matchScore += 12 * langWeight;
                matchedTerms.add(kw);
              } else if (token.length > 3 && normKw.includes(token)) {
                matchScore += 6 * langWeight;
                matchedTerms.add(token);
              }
            }
          }
        }
      }

      // Check translation names in all languages
      for (const lang of languages) {
        const trans = mudra.translations[lang];
        if (trans && trans.name) {
          const tName = this.normalize(trans.name);
          if (cleanQuery.includes(tName)) {
            matchScore += 35;
            matchedTerms.add(trans.name);
          }
        }
      }

      if (matchScore > 0) {
        scores.push({
          mudra,
          score: matchScore,
          matchedTerms: Array.from(matchedTerms)
        });
      }
    }

    // Sort descending by score
    scores.sort((a, b) => b.score - a.score);

    if (scores.length === 0) {
      return null;
    }

    const top = scores[0];
    // Calculate realistic confidence score between 75% and 99%
    const baseConfidence = Math.min(99, Math.max(72, Math.round(70 + Math.log2(top.score + 2) * 5.2)));

    return {
      bestMatch: top.mudra,
      confidence: baseConfidence,
      matchedTerms: top.matchedTerms,
      runnersUp: scores.slice(1, 4).map(s => s.mudra)
    };
  }
}

