const mudraTypeEl = document.getElementById("mudraType");
const mudraMeaningEl = document.getElementById("mudraMeaning");
const mudraFormationEl = document.getElementById("mudraFormation");
const mudraUsageEl = document.getElementById("mudraUsage");
const mudraShlokaEl = document.getElementById("mudraShloka");
const progressBar = document.getElementById("progressBar");
const confidenceText = document.getElementById("confidenceText");
const matchedTermsContainer = document.getElementById("matchedTerms");
const langTabButtons = document.querySelectorAll(".lang-tab-btn");
const audioNarrateBtn = document.getElementById("audioNarrateBtn");
const copyResultBtn = document.getElementById("copyResultBtn");
const alternativesContainer = document.getElementById("alternativesContainer");

// Catalog elements
