// -----------------------------------------------------------------------------
// 6. INITIALIZATION & EVENT LISTENERS
// -----------------------------------------------------------------------------
document.addEventListener("DOMContentLoaded", () => {
  // Populate Language Selector
  setupLanguageSelector();

  // Populate Example Chips for initial language
  updateExampleChips();

  // Populate Mudra Catalog
  renderCatalog();

  // Attach Event Handlers
  if (predictBtn) predictBtn.addEventListener("click", handlePredict);
  if (voiceBtn) voiceBtn.addEventListener("click", handleVoiceRecognition);
  if (clearBtn) clearBtn.addEventListener("click", handleClear);
  if (randomBtn) randomBtn.addEventListener("click", handleRandomMudra);
  if (audioNarrateBtn) audioNarrateBtn.addEventListener("click", toggleAudioNarration);
  if (copyResultBtn) copyResultBtn.addEventListener("click", handleCopyExplanation);

  // Smooth scroll button
  const startBtn = document.getElementById("startBtn");
  if (startBtn) {
    startBtn.addEventListener("click", () => {
      document.querySelector(".predict-section").scrollIntoView({ behavior: "smooth" });
    });
  }

  // Catalog search and filter
  if (catalogSearch) {
    catalogSearch.addEventListener("input", () => renderCatalog());
  }
  if (catalogCategoryFilter) {
    catalogCategoryFilter.addEventListener("change", () => renderCatalog());
  }

  // Display initial sample mudra so result card looks impressive on load
  const initialMudra = MUDRA_DATABASE[0]; // Pataka
  renderPredictionResult(initialMudra, 97, ["flat palm", "fingers straight"]);
});

// Setup Language Selector and listen for changes
function setupLanguageSelector() {
  if (!languageSelect) return;

  languageSelect.addEventListener("change", (e) => {
    const val = e.target.value.toLowerCase();
    switch (val) {
      case "kannada":
      case "kn":
        currentLanguage = "kn";
        break;
      case "tamil":
      case "ta":
        currentLanguage = "ta";
        break;
      case "telugu":
      case "te":
        currentLanguage = "te";
        break;
      case "malayalam":
      case "ml":
        currentLanguage = "ml";
        break;
      case "hindi":
      case "hi":
        currentLanguage = "hi";
        break;
      default:
        currentLanguage = "en";
        break;
    }
    onLanguageChanged();
  });

  // Language Tabs in Result Card
  langTabButtons.forEach(btn => {
    btn.addEventListener("click", (e) => {
      const lang = e.currentTarget.getAttribute("data-lang");
      if (lang && UI_STRINGS[lang]) {
        currentLanguage = lang;
        // Sync main dropdown
        if (languageSelect) {
          const optMap = { en: "English", kn: "Kannada", ta: "Tamil", te: "Telugu", ml: "Malayalam", hi: "Hindi" };
          languageSelect.value = optMap[lang];
        }
        onLanguageChanged();
      }
    });
  });
}

// When language changes: update placeholders, labels, example chips, and re-render current result
function onLanguageChanged() {
  const ui = UI_STRINGS[currentLanguage] || UI_STRINGS.en;

  // Update input placeholder and label
  const labelEl = document.querySelector(".predict-card label[for='description']");
  if (labelEl) labelEl.textContent = ui.describeLabel;
  if (descriptionInput) descriptionInput.placeholder = ui.placeholder;

  // Update example chips
  updateExampleChips();

  // Update active state on language tab buttons
  langTabButtons.forEach(btn => {
    const bLang = btn.getAttribute("data-lang");
    if (bLang === currentLanguage) {
      btn.classList.add("active");
    } else {
      btn.classList.remove("active");
    }
  });

  // Update audio button label
  if (audioNarrateBtn) {
    audioNarrateBtn.innerHTML = `<i class="fa-solid fa-volume-high"></i> ${ui.listenBtn}`;
  }

  // If a mudra is currently displayed, re-render its text in the newly selected language!
  if (currentPredictedMudra) {
    renderPredictionResult(currentPredictedMudra, currentConfidence);
  }

  // Also stop any ongoing speech synthesis if user switches language
  if (window.speechSynthesis) {
    window.speechSynthesis.cancel();
  }
}

// Update clickable sample chips
function updateExampleChips() {
  if (!exampleChipsContainer) return;
  const ui = UI_STRINGS[currentLanguage] || UI_STRINGS.en;
  exampleChipsContainer.innerHTML = "";

  ui.examples.forEach(sample => {
    const chip = document.createElement("button");
    chip.className = "example-chip";
    chip.type = "button";
    chip.innerHTML = `<i class="fa-solid fa-sparkles"></i> "${sample}"`;
    chip.addEventListener("click", () => {
      if (descriptionInput) {
        descriptionInput.value = sample;
        handlePredict();
      }
    });
    exampleChipsContainer.appendChild(chip);
  });
}

// -----------------------------------------------------------------------------
// 7. PREDICTION HANDLER
// -----------------------------------------------------------------------------
function handlePredict() {
  if (!descriptionInput) return;
  const text = descriptionInput.value.trim();

  if (!text) {
    alert("Please enter a mudra description or click an example!");
    return;
  }

  // Run NLP prediction
  const result = nlpEngine.predict(text, currentLanguage);

  if (result && result.bestMatch) {
    currentPredictedMudra = result.bestMatch;
    currentConfidence = result.confidence;
    renderPredictionResult(result.bestMatch, result.confidence, result.matchedTerms, result.runnersUp);
    
    // Scroll smoothly to result
    if (resultSection) {
      resultSection.scrollIntoView({ behavior: "smooth" });
    }
  } else {
    renderNoMatch();
  }
}

// Render the predicted Mudra with full multilingual explanations
function renderPredictionResult(mudra, confidence = 95, matchedTerms = [], runnersUp = []) {
  if (!mudra) return;
  currentPredictedMudra = mudra;
  currentConfidence = confidence;

  const trans = mudra.translations[currentLanguage] || mudra.translations.en;
  const ui = UI_STRINGS[currentLanguage] || UI_STRINGS.en;

  // Render SVG Vector Art
  if (mudraVisualContainer) {
    mudraVisualContainer.innerHTML = getMudraSVG(mudra.id);
  }

  // Update Mudra Name & Type
  if (mudraNameEl) {
    mudraNameEl.innerHTML = `
      <span>${trans.name}</span>
      <small class="sanskrit-title">${mudra.sanskrit}</small>
    `;
  }

  if (mudraTypeEl) {
    mudraTypeEl.textContent = trans.type;
  }

  // Update Explanation Sections
  if (mudraMeaningEl) {
    mudraMeaningEl.innerHTML = `<strong>${ui.meaningLabel}:</strong> ${trans.meaning}`;
  }

  if (mudraUsageEl) {
    mudraUsageEl.innerHTML = `<strong>${ui.usageLabel}:</strong> ${trans.usage}`;
  }

  if (mudraFormationEl) {
    mudraFormationEl.innerHTML = `<strong>${ui.formationLabel}:</strong> ${trans.formation}`;
  }

  if (mudraShlokaEl) {
    mudraShlokaEl.innerHTML = `<strong>${ui.shlokaLabel}:</strong> <em>${trans.shloka}</em>`;
  }

  // Update Progress / Confidence bar
  if (progressBar) {
    progressBar.style.width = `${confidence}%`;
    progressBar.style.backgroundColor = confidence > 85 ? "#10B981" : "#F59E0B";
  }

  if (confidenceText) {
    confidenceText.innerHTML = `<strong>${ui.confidence}:</strong> ${confidence}%`;
  }

  // Show Matched Terms Tags
  if (matchedTermsContainer) {
    if (matchedTerms && matchedTerms.length > 0) {
      matchedTermsContainer.innerHTML = `
        <span class="match-badge-label">Matched Keywords:</span>
        ${matchedTerms.slice(0, 5).map(term => `<span class="match-tag"><i class="fa-solid fa-check"></i> ${term}</span>`).join(" ")}
      `;
      matchedTermsContainer.style.display = "block";
    } else {
      matchedTermsContainer.style.display = "none";
    }
  }

  // Show Runners-up / Similar Mudras
  if (alternativesContainer) {
    if (runnersUp && runnersUp.length > 0) {
      alternativesContainer.innerHTML = `
        <h4>${ui.alternativesLabel}</h4>
        <div class="alternatives-grid">
          ${runnersUp.map(alt => {
            const altTrans = alt.translations[currentLanguage] || alt.translations.en;
            return `
              <div class="alt-mudra-chip" onclick="selectMudraById('${alt.id}')">
                <span class="alt-name">${altTrans.name}</span>
                <span class="alt-type">${alt.category === "asamyuta" ? "Single" : "Double"}</span>
              </div>
            `;
          }).join("")}
        </div>
      `;
      alternativesContainer.style.display = "block";
    } else {
      alternativesContainer.style.display = "none";
    }
  }
}

// Global helper for runner-up click
window.selectMudraById = function(mudraId) {
  const mudra = MUDRA_DATABASE.find(m => m.id === mudraId);
  if (mudra) {
    renderPredictionResult(mudra, 94);
    if (resultSection) {
      resultSection.scrollIntoView({ behavior: "smooth" });
    }
  }
};

// Render when no match is found
function renderNoMatch() {
  const ui = UI_STRINGS[currentLanguage] || UI_STRINGS.en;

  if (mudraVisualContainer) {
    mudraVisualContainer.innerHTML = `
      <div class="no-match-icon">
        <i class="fa-solid fa-hand-sparkles"></i>
      </div>
    `;
  }

  if (mudraNameEl) {
    mudraNameEl.innerHTML = `<span style="color:#F59E0B">${ui.noMatchTitle}</span>`;
  }

  if (mudraTypeEl) mudraTypeEl.textContent = "--";
  if (mudraMeaningEl) mudraMeaningEl.textContent = ui.noMatchText;
  if (mudraFormationEl) mudraFormationEl.textContent = "";
  if (mudraUsageEl) mudraUsageEl.textContent = "";
  if (mudraShlokaEl) mudraShlokaEl.textContent = "";

  if (progressBar) progressBar.style.width = "25%";
  if (confidenceText) confidenceText.textContent = `${ui.confidence}: 25%`;
  if (matchedTermsContainer) matchedTermsContainer.style.display = "none";
}

// -----------------------------------------------------------------------------
// 8. VOICE RECOGNITION (STT with Selected Language)
// -----------------------------------------------------------------------------
function handleVoiceRecognition() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

  if (!SpeechRecognition) {
    alert("Speech Recognition is not supported by your browser. Please try in Google Chrome or Microsoft Edge.");
    return;
  }

  const recognition = new SpeechRecognition();
  
  // Set speech recognition locale based on chosen language
  const localeMap = {
    en: "en-IN",
    kn: "kn-IN",
    ta: "ta-IN",
    te: "te-IN",
    ml: "ml-IN",
    hi: "hi-IN"
  };
  recognition.lang = localeMap[currentLanguage] || "en-IN";
  recognition.continuous = false;
  recognition.interimResults = false;

  const ui = UI_STRINGS[currentLanguage] || UI_STRINGS.en;
  voiceBtn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> ${ui.listening}`;
  voiceBtn.classList.add("listening-active");

  recognition.start();

  recognition.onresult = (event) => {
    const transcript = event.results[0][0].transcript;
    if (descriptionInput) {
      descriptionInput.value = transcript;
    }
    voiceBtn.innerHTML = `<i class="fa-solid fa-microphone"></i> ${ui.voiceBtn}`;
    voiceBtn.classList.remove("listening-active");
    // Automatically trigger prediction after voice recognition
    handlePredict();
  };

  recognition.onerror = (event) => {
    console.error("Speech recognition error:", event.error);
    voiceBtn.innerHTML = `<i class="fa-solid fa-microphone"></i> ${ui.voiceBtn}`;
    voiceBtn.classList.remove("listening-active");
  };

  recognition.onend = () => {
    voiceBtn.innerHTML = `<i class="fa-solid fa-microphone"></i> ${ui.voiceBtn}`;
    voiceBtn.classList.remove("listening-active");
  };
}

// -----------------------------------------------------------------------------
// 9. TEXT-TO-SPEECH (TTS Narration in Selected Language)
// -----------------------------------------------------------------------------
function toggleAudioNarration() {
  if (!window.speechSynthesis) {
    alert("Speech synthesis is not supported on this browser.");
    return;
  }

  if (window.speechSynthesis.speaking) {
    window.speechSynthesis.cancel();
    const ui = UI_STRINGS[currentLanguage] || UI_STRINGS.en;
    audioNarrateBtn.innerHTML = `<i class="fa-solid fa-volume-high"></i> ${ui.listenBtn}`;
    return;
  }

  if (!currentPredictedMudra) return;

  const trans = currentPredictedMudra.translations[currentLanguage] || currentPredictedMudra.translations.en;
  const narrationText = `${trans.name}. ${trans.type}. ${trans.meaning}. ${trans.usage}. Formation: ${trans.formation}.`;

  const utterance = new SpeechSynthesisUtterance(narrationText);
  currentSpeechUtterance = utterance;

  // Language code map
  const langCodes = {
    en: "en-IN",
    kn: "kn-IN",
    ta: "ta-IN",
    te: "te-IN",
    ml: "ml-IN",
    hi: "hi-IN"
  };
  utterance.lang = langCodes[currentLanguage] || "en-IN";
  utterance.rate = 0.92; // Slightly measured pace for classical diction

  // Pick matching voice if available
  const voices = window.speechSynthesis.getVoices();
  const matchedVoice = voices.find(v => v.lang.startsWith(utterance.lang.substring(0, 2)));
  if (matchedVoice) {
    utterance.voice = matchedVoice;
  }

  const ui = UI_STRINGS[currentLanguage] || UI_STRINGS.en;
  audioNarrateBtn.innerHTML = `<i class="fa-solid fa-stop"></i> ${ui.stopAudioBtn}`;

  utterance.onend = () => {
    audioNarrateBtn.innerHTML = `<i class="fa-solid fa-volume-high"></i> ${ui.listenBtn}`;
  };

  utterance.onerror = () => {
    audioNarrateBtn.innerHTML = `<i class="fa-solid fa-volume-high"></i> ${ui.listenBtn}`;
  };

  window.speechSynthesis.speak(utterance);
}

// -----------------------------------------------------------------------------
// 10. COPY EXPLANATION TO CLIPBOARD
// -----------------------------------------------------------------------------
function handleCopyExplanation() {
  if (!currentPredictedMudra) return;

  const trans = currentPredictedMudra.translations[currentLanguage] || currentPredictedMudra.translations.en;
  const copyText = `🪷 ${trans.name} (${currentPredictedMudra.sanskrit})\n` +
                   `Type: ${trans.type}\n\n` +
                   `Meaning: ${trans.meaning}\n\n` +
                   `Usage: ${trans.usage}\n\n` +
                   `Hand Formation: ${trans.formation}\n\n` +
                   `Shloka: ${trans.shloka}\n\n` +
                   `Predicted via MudraNLP`;

  navigator.clipboard.writeText(copyText).then(() => {
    const originalText = copyResultBtn.innerHTML;
    const ui = UI_STRINGS[currentLanguage] || UI_STRINGS.en;
    copyResultBtn.innerHTML = `<i class="fa-solid fa-check"></i> ${ui.copied}`;
    setTimeout(() => {
      copyResultBtn.innerHTML = originalText;
    }, 2000);
  });
}

// -----------------------------------------------------------------------------
// 11. CLEAR & RANDOM MUDRA HANDLERS
// -----------------------------------------------------------------------------
function handleClear() {
  if (descriptionInput) {
    descriptionInput.value = "";
    descriptionInput.focus();
  }
}

function handleRandomMudra() {
  const randomIndex = Math.floor(Math.random() * MUDRA_DATABASE.length);
  const randomMudra = MUDRA_DATABASE[randomIndex];
  const ui = UI_STRINGS[currentLanguage] || UI_STRINGS.en;

  const sampleKeywords = randomMudra.keywords[currentLanguage] || randomMudra.keywords.en;
  const prompt = sampleKeywords.slice(0, 3).join(", ");

  if (descriptionInput) {
    descriptionInput.value = prompt;
  }
  renderPredictionResult(randomMudra, 98, sampleKeywords.slice(0, 3));

  if (resultSection) {
    resultSection.scrollIntoView({ behavior: "smooth" });
  }
}

// -----------------------------------------------------------------------------
// 12. EXPLORER / FULL CATALOG GALLERY
// -----------------------------------------------------------------------------
function renderCatalog() {
  if (!catalogGrid) return;

  const query = catalogSearch ? catalogSearch.value.toLowerCase().trim() : "";
  const categoryFilter = catalogCategoryFilter ? catalogCategoryFilter.value : "all";

  catalogGrid.innerHTML = "";

  const filtered = MUDRA_DATABASE.filter(mudra => {
    // Category match
    if (categoryFilter !== "all" && mudra.category !== categoryFilter) {
      return false;
    }

    // Search query match in any language
    if (!query) return true;

    if (mudra.id.includes(query) || mudra.sanskrit.toLowerCase().includes(query)) return true;

    for (const lang of ["en", "kn", "ta", "te", "ml", "hi"]) {
      const trans = mudra.translations[lang];
      if (trans && (trans.name.toLowerCase().includes(query) || trans.meaning.toLowerCase().includes(query))) {
        return true;
      }
    }
    return false;
  });

  if (filtered.length === 0) {
    catalogGrid.innerHTML = `<p class="no-catalog-results">No mudras found matching "${query}".</p>`;
    return;
  }

  filtered.forEach(mudra => {
    const trans = mudra.translations[currentLanguage] || mudra.translations.en;
    const card = document.createElement("div");
    card.className = "catalog-card";
    card.innerHTML = `
      <div class="catalog-thumb">
        ${getMudraSVG(mudra.id)}
      </div>
      <div class="catalog-body">
        <span class="catalog-category-tag">${mudra.category === "asamyuta" ? "Asamyuta (Single)" : "Samyuta (Double)"}</span>
        <h4>${trans.name}</h4>
        <span class="catalog-sanskrit">${mudra.sanskrit}</span>
        <p>${trans.meaning.substring(0, 85)}...</p>
        <button type="button" class="catalog-view-btn" onclick="selectMudraById('${mudra.id}')">
          <i class="fa-solid fa-eye"></i> View & Explain
        </button>
      </div>
    `;
    catalogGrid.appendChild(card);
  });
}
